def missing_number_ranges(nums,lower,upper):
    present=sorted(x for x in set(nums) if lower<=x<=upper);answer=[];previous=lower-1
    for value in present+[upper+1]:
        if value>previous+1:answer.append([previous+1,value-1])
        previous=value
    return answer

